-- Notas crédito/débito internas sobre una orden prepago o una factura pospago ya generada — ver
-- el javadoc de NotaAjuste. Referencian exactamente una de las dos (nunca ambas, nunca ninguna).
CREATE TABLE "notas_ajuste" (
  "id_nota" BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY NOT NULL,
  "tipo" VARCHAR(10) NOT NULL,
  "id_orden_compra" BIGINT REFERENCES "ordenes_compra"("id_orden_compra"),
  "id_factura_pospago" BIGINT REFERENCES "facturas_pospago"("id_factura"),
  "id_cliente" INTEGER NOT NULL REFERENCES "clientes"("id_cliente"),
  "referencia" VARCHAR(50) NOT NULL UNIQUE,
  "monto_total" NUMERIC(15,2) NOT NULL,
  "motivo" VARCHAR(30) NOT NULL,
  "observaciones" TEXT,
  "fecha_generacion" TIMESTAMP NOT NULL,
  "id_generada_por" BIGINT NOT NULL REFERENCES "usuarios"("id_usuario"),
  CONSTRAINT "chk_notas_ajuste_un_solo_origen" CHECK (
    ("id_orden_compra" IS NOT NULL AND "id_factura_pospago" IS NULL) OR
    ("id_orden_compra" IS NULL AND "id_factura_pospago" IS NOT NULL)
  )
);

CREATE INDEX ON "notas_ajuste" ("id_orden_compra");
CREATE INDEX ON "notas_ajuste" ("id_factura_pospago");
CREATE INDEX ON "notas_ajuste" ("id_cliente");
